using DAL;
using Microsoft.Extensions.DependencyInjection;
using Utils.Interface;
namespace Tests;
public class AdminDashboardTests(ApiFactory f):ApiTest(f)
{
    [Fact]public async Task Admin_dashboard_counts_orders_refunds_IST_today_and_empty_defaults()
    {
        var admin=await Admin();var user=await LoginPhone("9890000094");Assert.Equal(403,(await user.Get("/api/admin/dashboard")).Status);var r=await admin.Get("/api/admin/dashboard");Assert.True(r.Status==200,r.ToString());Assert.Equal(19,r.Json.AsObject().Count);Assert.Equal(2,r.Json["customers"]!.GetValue<long>());Assert.Equal(0,r.Json["gmv_30d"]!.GetValue<long>());var seller=(await user.Post("/api/seller/register",new{display_name="Synthetic Dashboard Store"})).Json["id"]!.GetValue<string>();await ApiFactory.DbExecAsync("UPDATE sellers SET status='submitted' WHERE id=@seller",new{seller});
        using var scope=Factory.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<IMySqlDapperHelper>();var orders=scope.ServiceProvider.GetRequiredService<OrdersDAL>();var today=DateTime.UtcNow.AddMinutes(330).Date.AddMinutes(-330);var ids=new List<Guid>();await using(var tx=await db.BeginAsync()){for(var i=0;i<4;i++){var id=Guid.NewGuid();ids.Add(id);await orders.InsertOrderAsync(new(){Id=id,Number="SYNTH-DASH-"+i,UserId=Guid.Parse(user.Id),Status=i==3?"cancelled":"placed",PaymentMethod="cod",PaymentStatus="cod",ShipTo="{}",ItemsTotal=10000,GrandTotal=10000,RefundedTotal=i==0?1000:0,Currency="INR",FxRate=1,Fees="[]",IdempotencyKey=Guid.NewGuid().ToString(),PlacedAt=i==0?today:i==1?today.AddSeconds(-1):DateTime.UtcNow.AddDays(-31),CreatedAt=DateTime.UtcNow,UpdatedAt=DateTime.UtcNow},tx);}await orders.InsertSubOrderAsync(new(){Id=Guid.NewGuid(),OrderId=ids[0],SellerId=Guid.Parse(seller),Number="SYNTH-DASH-SUB",Status="packed",CommissionPaise=500,SettlementStatus="pending",CreatedAt=DateTime.UtcNow,UpdatedAt=DateTime.UtcNow},tx);await tx.CommitAsync();}
        r=await admin.Get("/api/admin/dashboard");Assert.True(r.Status==200,r.ToString());Assert.Equal(1,r.Json["sellers_pending_review"]!.GetValue<long>());Assert.Equal(1,r.Json["orders_today"]!.GetValue<long>());Assert.Equal(2,r.Json["orders_30d"]!.GetValue<long>());Assert.Equal(19000,r.Json["gmv_30d"]!.GetValue<long>());Assert.Equal(500,r.Json["commission_30d"]!.GetValue<long>());Assert.Equal(0,r.Json["active_sellers"]!.GetValue<long>());
        await ApiFactory.DbExecAsync("UPDATE sub_orders SET shipping_provider='fleet',ready_for_pickup_at=UTC_TIMESTAMP(6) WHERE order_id=@id",new{id=ids[0]});Assert.Equal(1,(await admin.Get("/api/admin/dashboard")).Json["delivery_waiting"]!.GetValue<long>());
        var cat=Guid.NewGuid();await ApiFactory.DbExecAsync("INSERT INTO categories(id,name,slug,image_url,commission_bps,default_gst_bps,position,is_active,required_details)VALUES(@cat,'Synthetic Dash','synthetic-dash','',500,500,0,1,'[]')",new{cat});var p=(await user.Post("/api/seller/products",new{category_id=cat,title="Synthetic Dashboard Product",hsn_code="6205",gst_bps=500,variants=new[]{new{sku="DASH-SKU",mrp_paise=20000,price_paise=10000,stock=5}}})).Json["id"]!.GetValue<string>();await ApiFactory.DbExecAsync("UPDATE products SET status='pending' WHERE id=@p",new{p});
        var review=Guid.NewGuid();await ApiFactory.DbExecAsync("INSERT INTO reviews(id,product_id,user_id,verified,rating,title,body,status,media,media_status,seller_reply,helpful_count,report_count)VALUES(@review,@p,@uid,0,4,'Synthetic','Synthetic','pending','[]','published','',0,0)",new{review,p,uid=user.Id});
        foreach(var(status,mediaStatus,media,count,expected)in new[]{("pending","published","[]",0,1),("published","pending","[{}]",0,1),("hidden","published","[]",1,1),("published","published","[]",0,0)}){await ApiFactory.DbExecAsync("UPDATE reviews SET status=@status,media_status=@mediaStatus,media=CAST(@media AS JSON),report_count=@count WHERE id=@review",new{review,status,mediaStatus,media,count});r=await admin.Get("/api/admin/dashboard");Assert.Equal(expected,r.Json["reviews_needing_attention"]!.GetValue<long>());}Assert.Equal(1,r.Json["products_pending_review"]!.GetValue<long>());
        var delivery=scope.ServiceProvider.GetRequiredService<DeliveryDAL>();var boy=Guid.NewGuid();await delivery.InsertPartnerAsync(new(){Id=boy,UserId=Guid.Parse(user.Id),Name="Synthetic Dash Partner",Phone="9890000094",VehicleType="bike",KycStatus="submitted",BankDetails="{}",CreatedAt=DateTime.UtcNow,UpdatedAt=DateTime.UtcNow});var sub=await ApiFactory.DbScalarAsync<Guid>("SELECT id FROM sub_orders WHERE order_id=@id",new{id=ids[0]});var assignment=Guid.NewGuid();await ApiFactory.DbExecAsync("INSERT INTO delivery_assignments(id,order_id,sub_order_id,delivery_boy_id,mode,status,reject_reason,assigned_at,status_at,cod_amount,cod_collected,cod_method,proof_photo,fee_paise,fail_reason,rating_comment,created_at)VALUES(@assignment,@oid,@sub,@boy,'manual','at_store','',UTC_TIMESTAMP(6),UTC_TIMESTAMP(6),0,0,'','',0,'','',UTC_TIMESTAMP(6))",new{assignment,oid=ids[0],sub,boy});
        foreach(var state in new[]{"offered","accepted","at_store","picked","on_the_way","reached"}){await ApiFactory.DbExecAsync("UPDATE delivery_assignments SET status=@state WHERE id=@assignment",new{state,assignment});Assert.Equal(0,(await admin.Get("/api/admin/dashboard")).Json["delivery_waiting"]!.GetValue<long>());}await ApiFactory.DbExecAsync("UPDATE delivery_assignments SET status='failed' WHERE id=@assignment",new{assignment});r=await admin.Get("/api/admin/dashboard");Assert.Equal(1,r.Json["delivery_waiting"]!.GetValue<long>());Assert.Equal(1,r.Json["delivery_kyc_pending"]!.GetValue<long>());
    }
}
